<?php
require_once __DIR__.'/../../includes/staff/operations.php';require_login();verify_csrf();$pdo=staff_db();$staff=current_staff();if($_SERVER['REQUEST_METHOD']==='POST'){$action=$_POST['action']??'all';if($action==='one'){$pdo->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE id=? AND staff_id=?')->execute([(int)$_POST['id'],$staff['id']]);}else{$pdo->prepare('UPDATE notifications SET is_read=1,read_at=NOW() WHERE staff_id=?')->execute([$staff['id']]);}staff_redirect('staff/pages/notifications.php');}$s=$pdo->prepare('SELECT * FROM notifications WHERE staff_id=? ORDER BY created_at DESC LIMIT 150');$s->execute([$staff['id']]);$rows=$s->fetchAll();$pageTitle='Notifications';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Inbox</p><h1>Notifications</h1><p class="muted">Task assignments and operational updates that need your attention.</p></div><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="all"><button class="btn">Mark all read</button></form></div><section class="staff-panel"><div class="list"><?php foreach($rows as $r):?><div class="list-row <?= !$r['is_read']?'unread':'' ?>"><div><b><?= h($r['title']) ?></b><small><?= h($r['message']) ?> · <?= h(date('j M Y, g:i A',strtotime($r['created_at']))) ?></small><?php if($r['related_type']==='project'&&$r['related_id']):?><a class="tiny" href="<?= h(ideare_root_url('staff/pages/project-view.php?id='.$r['related_id'])) ?>">Open project</a><?php elseif($r['related_type']==='customer'&&$r['related_id']):?><a class="tiny" href="<?= h(ideare_root_url('staff/pages/customer-view.php?id='.$r['related_id'])) ?>">Open customer</a><?php elseif($r['related_type']==='task'):?><a class="tiny" href="<?= h(ideare_root_url('staff/pages/tasks.php')) ?>">Open tasks</a><?php endif;?></div><?php if(!$r['is_read']):?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="one"><input type="hidden" name="id" value="<?= $r['id'] ?>"><button class="btn">Read</button></form><?php endif;?></div><?php endforeach;?><?php if(!$rows):?><div class="empty-state">No notifications yet.</div><?php endif;?></div></section></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
